import os
C={"men":"Men's Fashion","women":"Women's Fashion","electronics":"Electronics","beauty":"Beauty & Cosmetics","jewellery":"Jewellery & Accessories","home-living":"Home & Living","sports":"Sports & Fitness"}
ICON={"men":"👕","women":"👗","electronics":"🎧","beauty":"💄","jewellery":"💍","home-living":"🛋️","sports":"🏀"}
T=open('template.html').read()
def wrap(f,title,kind,body,cat="",root=""):
    h=T.replace('%TITLE%',title).replace('%KIND%',kind).replace('%CAT%',cat).replace('%R%',root).replace('%BODY%',body.replace('%R%',root))
    h=h.replace('%THREE%','<script src="https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.min.js"></script><script src="%sjs/three-scene.js"></script>'%root if kind=='home' else '')
    os.makedirs(os.path.dirname(f) or '.',exist_ok=True);open(f,'w').write(h)
def sec(t,b,c=""):return f'<section class="sec {c}"><div class="container"><h2 class="mb-4">{t}</h2>{b}</div></section>'
def head(t,s=""):return f'<div class="container py-5"><h1 class="grad">{t}</h1><p class="text-muted">{s}</p></div>'
LIST='''<div class="container pb-5"><div class="row g-4"><aside class="col-lg-3"><div class="glass p-3"><input id="f-q" class="form-control mb-3" placeholder="Search products" aria-label="Search"><label class="small">Category</label><select id="f-cat" class="form-select mb-3"></select><label class="small">Max price: <b id="pv"></b></label><input id="f-price" type="range" class="form-range mb-3" min="300" max="100000" step="100" value="100000"><label class="small">Minimum rating</label><select id="f-rate" class="form-select mb-3"><option value="0">Any</option><option value="3">3★ & up</option><option value="4">4★ & up</option></select><label class="small">Sort by</label><select id="f-sort" class="form-select mb-3"><option value="pop">Top rated</option><option value="lo">Price: low to high</option><option value="hi">Price: high to low</option><option value="disc">Biggest discount</option></select><button id="f-clear" class="btn btn-outline-light w-100">Clear filters</button></div></aside><div class="col-lg-9"><p id="count" class="text-muted"></p><div class="row g-4" id="grid"></div><ul class="pagination justify-content-center mt-4" id="pager"></ul></div></div></div>'''
def listing(f,t,cat="",root="",sub=""):wrap(f,t,'listing',head(t,sub)+LIST,cat,root)
# home
home=f'''<header class="hero"><canvas id="hero3d" aria-hidden="true"></canvas><div class="container"><div class="col-lg-7"><h1>DISCOVER A NEW WORLD OF <span class="grad">SHOPPING</span></h1><p class="lead text-muted my-4">From everyday essentials to extraordinary finds, discover everything you love at SHOPVIA.</p><a href="%R%shop.html" class="btn btn-glow btn-lg me-2">EXPLORE COLLECTION</a><a href="%R%shop.html" class="btn btn-outline-light btn-lg">SHOP NOW</a></div></div></header>'''
home+=sec('Shop by Category','<div class="row g-3">'+''.join(f'<div class="col-6 col-md-4 col-lg-3 reveal"><a class="catcard glass tilt" href="%R%categories/{k}.html"><img loading="lazy" alt="" src="data:image/svg+xml;utf8,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' viewBox=\'0 0 200 120\'%3E%3Crect width=\'200\' height=\'120\' fill=\'%23{["8B5CF6","38BDF8","6D28D9","0EA5E9","A855F7","3B82F6","7C3AED"][i]}\'/%3E%3Ctext x=\'100\' y=\'80\' font-size=\'60\' text-anchor=\'middle\'%3E{ICON[k]}%3C/text%3E%3C/svg%3E"><h6>{v}</h6></a></div>' for i,(k,v) in enumerate(C.items()))+'</div>')
home+=sec('Trending Products','<div class="row g-4" id="trending"><div class="col-12 skel"></div></div>')
home+=sec('New Arrivals','<div class="swiper" id="arrSwiper"><div class="swiper-wrapper" id="arrivals"></div></div>')
home+=f'<section class="sec"><div class="container"><div class="ab"><div class="text-center"><h2 class="grad">Exclusive Offers: up to 50% off</h2><p class="text-muted">Limited-time deals end in</p><div class="cd" data-cd></div><a href="%R%offers.html" class="btn btn-glow mt-4">Shop Deals</a><div class="display-3 float mt-3">🎁 🛍️ 🎧</div></div></div></div></section>'
home+=sec('Featured Collections','<div class="row g-4"><div class="col-md-6 reveal"><div class="glass p-5 h-100"><div class="display-1">🏃</div><h3>Move Better</h3><p class="text-muted">Gear for every workout, from yoga mats to running shoes.</p><a href="%R%categories/sports.html">Explore sports</a></div></div><div class="col-md-6 reveal"><div class="glass p-5 h-100"><div class="display-1">💡</div><h3>Make Home Yours</h3><p class="text-muted">Lamps, cushions and décor that change the mood of a room.</p><a href="%R%categories/home-living.html">Explore home</a></div></div></div>')
home+=sec('Why SHOPVIA?','<div class="row g-3 text-center">'+''.join(f'<div class="col-6 col-lg reveal"><div class="glass p-4 h-100"><i class="bi bi-{i} fs-1 grad"></i><h6 class="mt-2">{t}</h6></div></div>' for i,t in [("shield-check","Secure Shopping"),("truck","Fast Delivery"),("arrow-repeat","Easy Returns"),("award","Quality Products"),("headset","Customer Support")])+'</div>')
tests=[("Aarav","Beautiful products and super quick delivery!",5),("Meera","The deals here are unbeatable. Love the experience.",5),("Karthik","Easy returns made me a loyal customer.",4),("Divya","Great quality and friendly support team.",5)]
home+=sec('What Customers Say','<div class="swiper" id="tSwiper"><div class="swiper-wrapper">'+''.join(f'<div class="swiper-slide"><div class="glass p-4 h-100"><span class="star">{"★"*r}</span><p class="mt-2">“{q}”</p><b>{n}</b></div></div>' for n,q,r in tests)+'</div><div class="swiper-pagination position-relative mt-3"></div></div>')
home+='<section class="sec"><div class="container"><div class="glass p-5 text-center"><h3>Join the SHOPVIA newsletter</h3><form id="nl" class="row g-2 justify-content-center needs-validation" novalidate><div class="col-md-5"><input type="email" class="form-control" placeholder="you@example.com" required aria-label="Email"><div class="invalid-feedback">Enter a valid email address.</div></div><div class="col-auto"><button class="btn btn-glow">Subscribe</button></div></form></div></div></section>'
wrap('index.html','Home','home',home)
listing('shop.html','Shop All','','',"Browse all 42 products.")
for k,v in C.items():listing(f'categories/{k}.html',v,k,'../',f'Shop {v}.')
listing('offers.html','Offers & Deals','deals','','Products with 30% off or more.')
wrap('product-details.html','Product','product','<div class="container py-5"><div class="row g-5" id="pd"></div><h3 class="mt-5">Related products</h3><div class="row g-4" id="related"></div></div>')
wrap('wishlist.html','Wishlist','wishlist',head('Your Wishlist')+'<div class="container pb-5"><div class="row g-4" id="wl"></div></div>')
wrap('cart.html','Shopping Cart','cart',head('Shopping Cart')+'<div class="container pb-5"><div class="glass p-4" id="cartPage"></div></div>')
F=lambda i,l,t='text',x='':f'<div class="col-md-6"><label class="form-label" for="{i}">{l}</label><input id="{i}" name="{i}" type="{t}" class="form-control" required {x}><div class="invalid-feedback">Please enter a valid {l.lower()}.</div></div>'
wrap('checkout.html','Checkout','checkout',head('Checkout')+'<div class="container pb-5" id="co"><div class="demo mb-3">Demo checkout: no real payment, authentication or fulfilment happens.</div><div class="row g-4"><div class="col-lg-7"><form id="cf" class="glass p-4 row g-3 needs-validation" novalidate>'+F('name','Full name')+F('email','Email','email')+F('phone','Phone','tel','pattern="[0-9]{10}" maxlength="10"')+F('city','City')+'<div class="col-12"><label class="form-label" for="addr">Address</label><input id="addr" class="form-control" required><div class="invalid-feedback">Enter your address.</div></div>'+F('state','State')+F('zip','Postal code','text','pattern="[0-9]{6}" maxlength="6"')+'<div class="col-12"><label class="form-label">Payment method (simulated)</label><select name="pay" class="form-select"><option>UPI</option><option>Credit card</option><option>Debit card</option><option>Cash on Delivery</option></select></div><div class="col-12"><button class="btn btn-glow btn-lg">Place demo order</button></div></form></div><div class="col-lg-5"><div class="glass p-4" id="sum"></div></div></div></div>')
wrap('order-success.html','Order Success','success','<div class="container py-5 text-center" id="os"></div>')
def auth(f,t,mode):
    s=mode=='signup';pw=lambda i,l,e:f'<div class="mb-3"><label class="form-label" for="{i}">{l}</label><div class="input-group"><input id="{i}" class="form-control" type="password" minlength="8" required><button type="button" class="btn btn-outline-light" data-eye="{i}" aria-label="Show or hide password"><i class="bi bi-eye"></i></button></div></div>'
    b=f'<div class="container py-5" style="max-width:460px"><form id="af" data-mode="{mode}" class="glass p-4 needs-validation" novalidate><h2 class="grad">{t}</h2><div class="demo mb-3">Demo only: no real authentication.</div>'+('<div class="mb-3"><label class="form-label" for="nm">Name</label><input id="nm" class="form-control" required></div>' if s else '')+'<div class="mb-3"><label class="form-label" for="email">Email</label><input id="email" name="email" type="email" class="form-control" required></div>'+pw('pw','Password','')+('<div class="bar mb-3"><i id="meter" style="width:0"></i></div>'+pw('pw2','Confirm password','') if s else '<div class="d-flex justify-content-between mb-3"><label><input type="checkbox"> Remember me</label><a href="#">Forgot password?</a></div>')+f'<button class="btn btn-glow w-100">{t}</button><p class="mt-3 mb-0 text-center">{"Have an account? <a href=login.html>Login</a>" if s else "New here? <a href=signup.html>Sign up</a>"}</p></form></div>'
    wrap(f,t,'auth',b)
auth('login.html','Login','login');auth('signup.html','Sign Up','signup')
wrap('account.html','My Account','account','<div class="container py-5" id="acc"></div>')
st=lambda f,t,b:wrap(f,t,'static',head(t)+f'<div class="container pb-5"><div class="glass p-4">{b}</div></div>')
st('about.html','About Us','<p>SHOPVIA is an all-in-one shopping destination for fashion, electronics, beauty, jewellery, home essentials and sports gear. Shop smart. Live better.</p>')
st('contact.html','Contact Us','<form id="ct" class="row g-3 needs-validation" novalidate><div class="col-md-6"><input class="form-control" placeholder="Name" required></div><div class="col-md-6"><input type="email" class="form-control" placeholder="Email" required></div><div class="col-12"><textarea class="form-control" rows="4" placeholder="Message" required></textarea></div><div class="col-12"><button class="btn btn-glow">Send message</button></div></form><p class="mt-3 text-muted">Demo form: messages are not sent anywhere.</p>')
faq=[("How long does delivery take?","Demo answer: 3 to 7 business days."),("Can I return a product?","Yes, within 7 days of delivery."),("Is checkout real?","No. SHOPVIA is a frontend demo; no payments are processed.")]
st('faq.html','FAQ','<div class="accordion">'+''.join(f'<div class="accordion-item"><h2 class="accordion-header"><button class="accordion-button collapsed" data-bs-toggle="collapse" data-bs-target="#q{i}">{q}</button></h2><div id="q{i}" class="accordion-collapse collapse"><div class="accordion-body">{a}</div></div></div>' for i,(q,a) in enumerate(faq))+'</div>')
st('privacy.html','Privacy Policy','<p>This demo stores your cart, wishlist and demo account in your browser LocalStorage only. Nothing is sent to a server.</p>')
st('terms.html','Terms & Conditions','<p>SHOPVIA is a demonstration project. Products, prices and orders are fictional.</p>')
wrap('404.html','Page Not Found','static','<div class="container py-5 text-center"><div class="display-1 float">🛸</div><h1 class="grad">404: Page not found</h1><a class="btn btn-glow" href="index.html">Back to home</a></div>')
open('README.md','w').write('# SHOPVIA\nFrontend demo (HTML/CSS/vanilla JS, Bootstrap 5, Three.js, GSAP, Swiper). CDN libraries need internet.\n\n## Run\n`python3 -m http.server 8000` then open http://localhost:8000\n\n## Rebuild pages\nEdit template.html / build.py, then `python3 build.py`.\n\nCheckout, login and orders are simulated; LocalStorage only.\n')
